local config = {
  ui_story_31110101_1_dialog_content = "It all started one day when I was in the cafe sorting out the books on the shelves.",
  ui_story_31110101_2_dialog_content = "After the cafe opened, it had become the number one spot for fun and relaxation for a lot of people.",
  ui_story_31110101_3_dialog_content = "And not only for the great coffee there—a lot of people are drawn to what is on offer on the bookshelves.",
  ui_story_31110101_4_dialog_content = "However, with so many people taking an interest in the books, keeping the shelves organized had become a problem in itself.",
  ui_story_31110101_5_dialog_content = "Let me see... The Lost Secret Territory should go over here.",
  ui_story_31110101_6_dialog_content = "And the Nameless Mercenary's Notes... That should go in the \"Biography\" section on the lower shelf.",
  ui_story_31110101_7_dialog_content = "Illumina Social Guidelines... should be at the top, in the \"Society\" section.",
  ui_story_31110101_8_dialog_content = "I can't reach it. Firefly! Little help?",
  ui_story_31110101_9_dialog_content = "\"Need help? Let me help you out!\"",
  ui_story_31110101_10_dialog_content = "Wait... Why are you <color=#FFB400>playing Vice's voice</color>? When did you record that?",
  ui_story_31110101_11_dialog_content = "\"Just leave them to me. I'll handle everything!\"",
  ui_story_31110101_12_dialog_content = "\"It'd be great if you could help me out, though!\"",
  ui_story_31110101_13_dialog_content = "<anim type=Shake><size=45>\"It'd be great if you could help me out, though!\"</size></anim>",
  ui_story_31110101_14_dialog_content = "I heard you the first time!",
  ui_story_31110101_15_dialog_content = "You just need to help me put Illumina Social Guidelines up there, and I can take care of the rest!",
  ui_story_31110101_16_dialog_content = "After adding these new features, the Fireflies have started to become a little too smart.",
  ui_story_31110101_17_dialog_content = "And now... Northland Geographica.",
  ui_story_31110101_18_dialog_content = "Huh?",
  ui_story_31110101_19_dialog_content = "<color=#e8d9bb>Clusters of tiny crystals are spread across the book's beautiful cover.</color>",
  ui_story_31110101_20_dialog_content = "Crystals?",
  ui_story_31110101_21_dialog_content = "It's not just this book, they're all over An Adventurer's Voyage and The Aurora Expedition, too!",
  ui_story_31110101_22_dialog_content = "But there aren't any crystals on those weird, old books like Doomsday Chronicles and Unknown Ancient Tomes...",
  ui_story_31110101_23_dialog_content = "What's going on here...?",
  ui_story_31110101_24_dialog_content = "Excuse me.",
  ui_story_31110101_25_dialog_content = "Oh, PlayerName...",
  ui_story_31110101_26_dialog_content = "Hey, Beryl... Are you here to borrow some books?",
  ui_story_31110101_27_dialog_content = "I have a book to return... This...",
  ui_story_31110101_28_dialog_content = "<color=#FFB400>Rediesel Recipe</color>?",
  ui_story_31110101_29_option_content = "I haven't read it yet.",
  ui_story_31110101_30_dialog_content = "How was it?",
  ui_story_31110101_31_dialog_content = "It's...",
  ui_story_31110101_32_dialog_content = "It's a book about the cuisine of the Rediesel Desert.",
  ui_story_31110101_33_dialog_content = "That seems pretty clear.",
  ui_story_31110101_34_dialog_content = "...",
  ui_story_31110101_35_dialog_content = "It's much more than that!",
  ui_story_31110101_36_dialog_content = "Rediesel Recipe introduces all kinds of unique food...",
  ui_story_31110101_37_dialog_content = "But it's also about the author, Uncle Johnny, and his life... His philosophy... It's...",
  ui_story_31110101_X37_dialog_content = "<size=30>A really amazing book...</size>",
  ui_story_31110101_38_option_content = "I remember this book...",
  ui_story_31110101_39_dialog_content = "The author claims to be a part-time traveler and full-time foodie, the Iron Chef of the Rediesel Desert.",
  ui_story_31110101_40_dialog_content = "He's called Uncle Johnny, right?",
  ui_story_31110101_41_dialog_content = "Hmm... <size=30>I didn't think you'd have read it, PlayerName.</size>",
  ui_story_31110101_42_dialog_content = "Yeah, after all, that Sandstone rice recipe is to die for.",
  ui_story_31110101_43_dialog_content = "But he uses such graphic language... I don't think it's really suitable for younger readers.",
  ui_story_31110101_44_dialog_content = "But... This book definitely has a lot of passion in its pages... Yeah.",
  ui_story_31110101_45_dialog_content = "The camels of the desert... and the glistening sea... It's all so romantic.",
  ui_story_31110101_46_dialog_content = "(I never knew Beryl could open up so much when talking about books...)",
  ui_story_31110101_47_dialog_content = "(She's completely different from her usual silent self.)",
  ui_story_31110101_48_dialog_content = "I'll put it back on the shelf for you. If there's anything else you'd like to read...",
  ui_story_31110101_49_dialog_content = "Hold on... The back of this book is covered in crystals!",
  ui_story_31110101_50_dialog_content = "It looks like they even form a kind of... picture...? It looks like a head... Is that... Uncle Johnny!?",
  ui_story_31110101_51_dialog_content = "Beryl! Are you the one who's been covering these books with crystals!?",
  ui_story_31110101_52_dialog_content = "Sorry...",
  ui_story_31110101_53_dialog_content = "I've been setting up a <color=#FFB400>book club</color> recently, so... I borrowed a bunch of books from the Colossus.",
  ui_story_31110101_54_dialog_content = "I lose control sometimes... When I see something that fascinates me... crystals start growing all over the pages.",
  ui_story_31110101_56_dialog_content = "But... Don't worry. I can get rid of them.",
  ui_story_31110101_X56_dialog_content = "Here.",
  ui_story_31110101_57_dialog_content = "I just need to focus...",
  ui_story_31110101_58_dialog_content = "They're actually gone! I'll put the book back on the shelf, then.",
  ui_story_31110101_59_dialog_content = "By the way, is there anything else you like, besides this book?",
  ui_story_31110101_60_dialog_content = "Yes...",
  ui_story_31110101_61_dialog_content = "If you have time, I recommend reading Fables of Astra.",
  ui_story_31110101_62_dialog_content = "It's like a collection of different stories? I haven't read it yet.",
  ui_story_31110101_63_dialog_content = "Yes, there are a lot of philosophical tales in it.",
  ui_story_31110101_64_dialog_content = "Like this one—The White Flower.",
  ui_story_31110101_65_dialog_content = "\"A flower stretched its petals to show the world its purity.\"",
  ui_story_31110101_66_dialog_content = "\"Whether showered in white pigment or scrubbed clean with dew...\"",
  ui_story_31110101_67_dialog_content = "\"There was no way to prove that its white was most true.\"",
  ui_story_31110101_68_dialog_content = "(Beryl's voice is so beautiful when she reads!)",
  ui_story_31110101_69_dialog_content = "(What are those Fireflies doing here? Are they secretly <color=#FFB400>recording</color> us?)",
  ui_story_31110101_70_dialog_content = "\"But when trapped in the earth, when it was completely covered with the blackest soil.\"",
  ui_story_31110101_71_dialog_content = "\"Only then did others praise it for its purity.\"",
  ui_story_31110101_72_dialog_content = "Although the stories are fictional, they reflect the nature of reality, and always make me think a lot.",
  ui_story_31110101_73_dialog_content = "This flower story... It's just like the story of my parents...",
  ui_story_31110101_74_dialog_content = "Your parents?",
  ui_story_31110101_75_dialog_content = "Hmm...",
  ui_story_31110101_76_dialog_content = "I try to forget those times every day, but...",
  ui_story_31110101_77_dialog_content = "My parents were framed. In order to prove their innocence, and to save me from becoming a test subject...",
  ui_story_31110101_78_dialog_content = "They went to Umbraton to fight the Eclipsites drawn to the Sanguine Crystals, despite the ban imposed by the Lumopolis nobility.",
  ui_story_31110101_79_dialog_content = "In the end, they were buried... And I...",
  ui_story_31110101_80_dialog_content = "The Sanguine Crystal being contaminated by Darkflow is like a nightmare.",
  ui_story_31110101_81_dialog_content = "How I wish this nightmare would end and disappear from my memory forever...",
  ui_story_31110101_82_option_content = "Beryl...",
  ui_story_31110101_83_dialog_content = "Beryl...",
  ui_story_31110101_84_dialog_content = "Huh? Who was calling my name like PlayerName?",
  ui_story_31110101_85_dialog_content = "It's the Fireflies. They've been updated with a recording function recently, and they occasionally replay the audio they've recorded...",
  ui_story_31110101_86_dialog_content = "Did they record me talking just now...?",
  ui_story_31110101_87_dialog_content = "\"A flower stretched its petals to show the world its purity.\"",
  ui_story_31110101_88_dialog_content = "\"Only then did others praise it for its purity.\"",
  ui_story_31110101_89_dialog_content = "\"This flower story... It's just like the story of my parents...\"",
  ui_story_31110101_X89_dialog_content = "...",
  ui_story_31110101_90_dialog_content = "I knew it... My sins will never be erased from this world.",
  ui_story_31110101_91_dialog_content = "Will I never be allowed to live in peace?",
  ui_story_31110101_92_dialog_content = "\"Beryl... You will never escape.\"",
  ui_story_31110101_93_dialog_content = "That nightmare...",
  ui_story_31110101_94_dialog_content = "<size=45>Aaaah!</size>",
  ui_story_31110101_95_dialog_content = "Wait a second, Beryl! The crystals!",
  ui_story_31110101_96_dialog_content = "There are crystals everywhere! You're going to fill the entire Cafe!",
  ui_story_31110101_97_dialog_content = "Calm down, Beryl!",
  ui_story_31110101_98_dialog_content = "I almost thought I'd end up buried alive by crystals...",
  ui_story_31110101_99_dialog_content = "Sorry, PlayerName... I shouldn't have become so emotional.",
  ui_story_31110101_100_dialog_content = "Those voice recordings brought up some bad memories.",
  ui_story_31110101_101_dialog_content = "I'm the one who should apologize. I didn't mean to record what you said. It was those darn Fireflies...",
  ui_story_31110101_102_dialog_content = "Huh?",
  ui_story_31110101_103_dialog_content = "You see, I asked Fleur to add a recording function to the Fireflies.",
  ui_story_31110101_104_dialog_content = "Before he finished, Genevieve suddenly showed up and told him that only \"worthy quotes\" should be recorded.",
  ui_story_31110101_105_dialog_content = "Then Bonacie came along and said they should only record sounds that are pleasing to the ear.",
  ui_story_31110101_106_dialog_content = "And then Eicy popped up to say she wanted the Firefly recordings to be more human...",
  ui_story_31110101_107_dialog_content = "You know how Fleur always tries to please everyone, so of course, he promised to add everything they asked for. And so, they ended up like this...",
  ui_story_31110101_108_dialog_content = "So... <size=30>So that's it</size>?",
  ui_story_31110101_109_dialog_content = "But don't worry, anything you don't want the others to hear can be deleted.",
  ui_story_31110101_110_dialog_content = "So, what do you think?",
  ui_story_31110101_111_dialog_content = "\"Take some rest.\"",
  ui_story_31110101_112_dialog_content = "That's what Carleen always says.",
  ui_story_31110101_113_dialog_content = "Beryl, I've been haunted by my own nightmares, and I know how terrible it can be...",
  ui_story_31110101_114_dialog_content = "But there's no need to push yourself so hard. I believe that time heals all wounds.",
  ui_story_31110101_115_dialog_content = "And you have all these books to read! There will always be answers waiting for you on their pages!",
  ui_story_31110101_116_dialog_content = "It really does feel like, when I touch these books, my heart becomes calm.",
  ui_story_31110101_117_dialog_content = "Thank you, PlayerName.",
  ui_story_31110101_118_dialog_content = "Oh yes, I should return this book to you. Here you go...",
  ui_story_31110101_119_dialog_content = "Hmm? There are some crystals on it...",
  ui_story_31110101_120_dialog_content = "Focus...",
  ui_story_31110101_121_dialog_content = "Huh? Why can't I get rid of the crystals on this book?",
  ui_story_31110101_122_dialog_content = "<size=30>Are these crystals really an unforgivable curse?</size>",
  ui_story_31110101_123_dialog_content = "Don't worry about that.",
  ui_story_31110101_124_dialog_content = "Huh?",
  ui_story_31110101_125_dialog_content = "If you can't get rid of them, just leave them there. These crystals are just like your personal notes!",
  ui_story_31110101_126_dialog_content = "Wherever you find a bunch of crystals, you know that this part comes highly recommended by Beryl! It'll even make people pay extra attention to your favorite pages!",
  ui_story_31110101_127_dialog_content = "Problem solved!",
  ui_story_31110101_128_dialog_content = "PlayerName...",
  ui_story_31110101_129_dialog_content = "So, Beryl... What else would you like to read?",
  ui_story_31110101_130_dialog_content = "I'll head off to Umbraton soon to get some more books and keep the bookshelves filled with an even more wonderful collection.",
  ui_story_31110101_131_dialog_content = "If that's the case, then I want <color=#FFB400><size=30>The Girl</size></color>...",
  ui_story_31110101_132_dialog_content = "<color=#FFB400>The Girl</color>?",
  ui_story_31110101_133_dialog_content = "Never mind... Goodbye, PlayerName.",
  ui_story_31110101_134_dialog_content = "What is this \"The Girl\" book she mentioned?",
  ui_story_31110101_135_dialog_content = "May the Truth bless you, my dear PlayerName.",
  ui_story_31110101_136_dialog_content = "Are you here to return a book, too?",
  ui_story_31110101_137_dialog_content = "That's right, I'm returning this Dream's Covenant.",
  ui_story_31110101_138_dialog_content = "The lunatic had only seen a glimpse of the truth, thinking it was the whole picture.",
  ui_story_31110101_139_dialog_content = "But how can the wrong direction lead to the right conclusion? It's all imaginary nonsense, of course.",
  ui_story_31110101_140_dialog_content = "But not bad if you're looking for a little light entertainment.",
  ui_story_31110101_141_dialog_content = "I have no idea what you're talking about.",
  ui_story_31110101_142_dialog_content = "Just my thoughts on the book. Now, as you were!",
  ui_story_31110101_143_dialog_content = "Wait, Faust!",
  ui_story_31110101_144_dialog_content = "You've read a lot of books in your time... Would you happen to know a book called \"The Girl\"?",
  ui_story_31110101_145_dialog_content = "\"The Girl\", you say?",
  ui_story_31110101_146_dialog_content = "Hahaha! It really is a rare treat hearing such words coming from your mouth, PlayerName.",
  ui_story_31110101_147_dialog_content = "Of course I know it.",
  ui_story_31110101_148_dialog_content = "It's a sweet and romantic lie—the sharpest words, penned in lingering ink.",
  ui_story_31110101_149_dialog_content = "A flavor most suitable for young girls, naturally.",
  ui_story_31110101_150_option_content = "Can you cut it with the riddles!?",
  ui_story_31110101_151_dialog_content = "Are we speaking the same language here?",
  ui_story_31110101_152_dialog_content = "Is love so difficult for you to understand?",
  ui_story_31110101_153_option_content = "Oh, I get it!",
  ui_story_31110101_154_dialog_content = "It's a love story!",
  ui_story_31110101_155_dialog_content = "You should also read more books of that sort, PlayerName.",
  ui_story_31110101_156_dialog_content = "Only then will you understand the feelings of a girl who appears indifferent at first glance, but is gentle at heart.",
  ui_story_31110601_1_dialog_content = "<color=#e8d9bb>Report: Abnormal cloud activity and increased air temperature detected. High probability of rain.</color>",
  ui_story_31110601_2_dialog_content = "(My heart is pounding...)",
  ui_story_31110601_3_dialog_content = "(I want to breathe, but it feels like there's a weight crushing my chest. It's suffocating...)",
  ui_story_31110601_4_dialog_content = "Hurry...",
  ui_story_31110601_5_dialog_content = "(Is someone calling me...?)",
  ui_story_31110601_6_dialog_content = "(Am I starting to hallucinate? Maybe I should just close my eyes...)",
  ui_story_31110601_7_dialog_content = "Wake up, PlayerName! Open your eyes!",
  ui_story_31110601_8_dialog_content = "B... Beryl?",
  ui_story_31110601_9_dialog_content = "You're finally awake! Thank goodness you're okay...",
  ui_story_31110601_10_dialog_content = "Could... *Coughing* Could you please... let go of me? I can't breathe...",
  ui_story_31110601_11_dialog_content = "<size=30>I-I'm sorry...!</size> Can you stand?",
  ui_story_31110601_12_dialog_content = "I-I think so.",
  ui_story_31110601_13_dialog_content = "Whew... Much better. Thanks for pulling me out of the sea.",
  ui_story_31110601_14_dialog_content = "You really gave me a scare just now...",
  ui_story_31110601_15_dialog_content = "You rushed to me, but then you got swept out by the waves...",
  ui_story_31110601_16_dialog_content = "Th-That's because...",
  ui_story_31110601_17_dialog_content = "(It was because I noticed her swimming out there.)",
  ui_story_31110601_18_dialog_content = "(But then, all of a sudden, she disappeared under the surface. I thought she was drowning...)",
  ui_story_31110601_19_dialog_content = "(So right when I lunged out to save her, a wave hit me in the face and knocked me down.)",
  ui_story_31110601_20_dialog_content = "(...)",
  ui_story_31110601_21_dialog_content = "(I think it's time to do something about this bad habit of mine.)",
  ui_story_31110601_23_dialog_content = "Sorry...",
  ui_story_31110601_24_dialog_content = "What were you doing in the sea, anyway? Why isn't Raphael with you?",
  ui_story_31110601_25_dialog_content = "I broke my toy shovel when we were making a sandcastle, so she went to get a new one...",
  ui_story_31110601_26_dialog_content = "You two were making a sandcastle castle?",
  ui_story_31110601_27_dialog_content = "Yep! Summer's almost over, and we're going to leave this place soon.",
  ui_story_31110601_28_dialog_content = "So before we do, I want to try the best I can to make a bigger, more beautiful sandcastle!",
  ui_story_31110601_29_dialog_content = "Like one last celebration for the summer...",
  ui_story_31110601_30_dialog_content = "I found a really nice shell for decorating the sandcastle, but it got washed out to sea...",
  ui_story_31110601_31_dialog_content = "So I went looking for it.",
  ui_story_31110601_32_dialog_content = "It's probably too late now, isn't it?",
  ui_story_31110601_33_dialog_content = "Rescuing me must have made you lose sight of it, right? What kind of shell was it?",
  ui_story_31110601_34_dialog_content = "It was a big, silver shell with these really beautiful lines. It's bigger than most shells on the beach.",
  ui_story_31110601_35_dialog_content = "Got it! I'll take responsibility by helping you find another shell for your sandcastle castle, okay?",
  ui_story_31110601_36_dialog_content = "O-Okay...! Thank you, PlayerName! I'll be waiting by my sandcastle castle!",
  ui_story_31110601_37_dialog_content = "<color=#e8d9bb>Some time later...</color>",
  ui_story_31110601_38_dialog_content = "I'm back!",
  ui_story_31110601_39_dialog_content = "Welcome back, PlayerName! I hope you didn't have too much trouble?",
  ui_story_31110601_40_dialog_content = "This is the sandcastle we built today. <size=30>I'm just putting a few extra touches on it.</size>",
  ui_story_31110601_41_dialog_content = "This is... a sandcastle?",
  ui_story_31110601_42_dialog_content = "From the bottom it does look like one, but the detail put into the windows and doors is a little too much...",
  ui_story_31110601_43_dialog_content = "There's even a maiden in the highest tower...",
  ui_story_31110601_44_dialog_content = "Her wings are perfectly designed, and every single feather is distinct.",
  ui_story_31110601_46_dialog_content = "It's a masterpiece... I can't help but wonder if the sculptures in Lumopolis were also Beryl's works...",
  ui_story_31110601_47_dialog_content = "PlayerName?",
  ui_story_31110601_48_dialog_content = "Ahem, I mean, these shells are perfect decorations for your sandcastle!",
  ui_story_31110601_49_dialog_content = "Also, these crystals... Could they be...?",
  ui_story_31110601_50_dialog_content = "Yes... you see, I've been practicing controlling my power lately.",
  ui_story_31110601_51_dialog_content = "Before, I was only using my power for the True Order.",
  ui_story_31110601_52_dialog_content = "But now, I realize that it isn't just something scary. It... can be beautiful, too.",
  ui_story_31110601_53_dialog_content = "It feels weird to say it, but ever since that day, I feel as though a heavy burden was taken off of me...",
  ui_story_31110601_54_dialog_content = "My heart feels so light now.",
  ui_story_31110601_55_dialog_content = "That's great to hear, Beryl.",
  ui_story_31110601_56_dialog_content = "I think I have something else that'll make you even happier.",
  ui_story_31110601_57_dialog_content = "Here, a new shell!",
  ui_story_31110601_58_dialog_content = "It took me some time to find one over there. This is the biggest one I could find.",
  ui_story_31110601_59_dialog_content = "It's even better than the one I found earlier!",
  ui_story_31110601_60_dialog_content = "Now to put it in its place...",
  ui_story_31110601_61_dialog_content = "It's such a shame we have to leave something so beautiful here on the beach.",
  ui_story_31110601_62_dialog_content = "All we can do is leave it at the mercy of the sun and the wind.",
  ui_story_31110601_63_dialog_content = "The air is kind of stuffy today, too. There's a good chance that it's going to rain.",
  ui_story_31110601_64_dialog_content = "And when the tide comes in, it'll eventually wash it all away...",
  ui_story_31110601_65_dialog_content = "If only there was a way to put it on the Colossus...",
  ui_story_31110601_66_dialog_content = "Something this big... It wouldn't be easy to do... is it?",
  ui_story_31110601_67_dialog_content = "(I don't think it would even fit through the Colossus' door.)",
  ui_story_31110601_68_dialog_content = "... I-It's okay! Even if we can't take it with us...",
  ui_story_31110601_69_dialog_content = "We can always come back next year to build a new one!",
  ui_story_31110601_70_dialog_content = "And the year after that, and every year after... As long as it's what you want, Beryl, we can come back every year.",
  ui_story_31110601_71_dialog_content = "I'm back, Beryl!",
  ui_story_31110601_72_dialog_content = "See? I brought you a new bucket, as well as a new shovel and pick!",
  ui_story_31110601_73_dialog_content = "Oh? PlayerName! Are you here to build a sand castle, too?",
  ui_story_31110601_74_dialog_content = "It's an art, you know? It's no different from painting or sculpting.",
  ui_story_31110601_75_dialog_content = "Are you sure you have that kind of skill, PlayerName...?",
  ui_story_31110601_76_dialog_content = "Hey! How can you say that when you've never even seen my artwork?!",
  ui_story_31110601_77_dialog_content = "Oh, I know plenty about your art. Vice has told me all about it...",
  ui_story_31110601_78_dialog_content = "Here's the truth, Beryl.",
  ui_story_31110601_79_dialog_content = "Vice once described the cat's whiskers on PlayerName's drawing as looking as tentacles of an octopus!",
  ui_story_31110601_80_dialog_content = "You...! I...",
  ui_story_31110601_81_dialog_content = "Anyway, what were you two talking about just now?",
  ui_story_31110601_82_dialog_content = "We were thinking of a way to take the sandcastle with us...",
  ui_story_31110601_83_dialog_content = "Raphael, you're so smart and knowledgeable. Do you happen to have any ideas?",
  ui_story_31110601_84_dialog_content = "Oh, you really know how to butter someone up before asking for something, don't you Beryl? Well, you aren't wrong, I am very smart!",
  ui_story_31110601_85_dialog_content = "I'll think of something, so don't you worry your pretty little head any longer!",
  ui_story_31110601_86_dialog_content = "...",
  ui_story_31110601_87_dialog_content = "You don't have a clue, do you...?",
  ui_story_31110601_88_dialog_content = "Pipe down! Can't you see I'm trying to think over here?",
  ui_story_31110601_89_dialog_content = "Let's see... Could we entrust the Courier Union to split it and help us to deliver?",
  ui_story_31110601_90_dialog_content = "That sounds even harder than just rebuilding it on the Colossus...",
  ui_story_31110601_91_dialog_content = "Then... what if we build the sandcastle up high into the sky, like a landmark?",
  ui_story_31110601_92_dialog_content = "That way, we can see it from wherever we are, you wouldn't have to carry it around, either!",
  ui_story_31110601_93_dialog_content = "Even if we used every grain of sand on this beach, I'm pretty sure we still wouldn't be able to make it that tall...",
  ui_story_31110601_94_dialog_content = "We could always freeze it...",
  ui_story_31110601_95_dialog_content = "That won't stop the sun and rain from wearing it down, though.",
  ui_story_31110601_96_dialog_content = "Ice can still melt, after all.",
  ui_story_31110601_97_dialog_content = "In that case, we have no other choice but to use our last resort.",
  ui_story_31110601_98_dialog_content = "I heard a famous saying recently: \"Art is an Explosion!\"",
  ui_story_31110601_99_dialog_content = "Huh?",
  ui_story_31110601_100_dialog_content = "If we blow up the sandcastle, the result might even look like fireworks!",
  ui_story_31110601_101_dialog_content = "The sight of the explosion will be burned into our minds, becoming an unforgettable memory.",
  ui_story_31110601_X101_dialog_content = "In a way, the sandcastle will also be born anew!",
  ui_story_31110601_102_dialog_content = "Just imagine it! Beryl, smiling as the pink sands rain down around her...",
  ui_story_31110601_X102_dialog_content = "Ahh, what a beautiful scene!",
  ui_story_31110601_103_dialog_content = "Incidentally, so long as my Holy Water Shell is buried in the castle's foundation, I'm sure the explosion will set the scene perfectly.",
  ui_story_31110601_104_dialog_content = "So, what do you think? It's a great idea, right?",
  ui_story_31110601_105_dialog_content = "...",
  ui_story_31110601_106_dialog_content = "H-Hey! Put me down, PlayerName! I can't reach the ground!",
  ui_story_31110601_107_dialog_content = "What kind of evil has been cooking in that head of yours today?",
  ui_story_31110601_108_dialog_content = "Beryl worked so hard on that castle! How could you even think about blowing it up?!",
  ui_story_31110601_109_dialog_content = "Oh, it was just a suggestion! I wasn't really planning on blowing it up!",
  ui_story_31110601_110_dialog_content = "I guess taking the sandcastle with us is out of the question...",
  ui_story_31110601_111_dialog_content = "Yep...",
  ui_story_31110601_112_dialog_content = "The stress is starting to make me tear up...",
  ui_story_31110601_113_dialog_content = "But wait, I'm not crying at all! So why are there tears going down my face?",
  ui_story_31110601_114_dialog_content = "I think... It's raining?",
  ui_story_31110601_115_dialog_content = "I didn't expect the rain would come so quickly...",
  ui_story_31110601_116_dialog_content = "Beryl's sand sculptures...",
  ui_story_31110601_117_dialog_content = "<color=#e8d9bb>The rain is slowly breaking the sandcastle down.</color>",
  ui_story_31110601_118_dialog_content = "We need to find something to block the rain, or else it's going to...",
  ui_story_31110601_119_dialog_content = "It's okay, PlayerName.",
  ui_story_31110601_X103_dialog_content = "I completely understand.",
  ui_story_31110601_120_dialog_content = "Sandcastles aren't meant to last forever. After all, they're made of sand.",
  ui_story_31110601_121_dialog_content = "If we really wanted to make something that could last forever, then <size=30>from the beginning...</size>",
  ui_story_31110601_122_dialog_content = "I should have chosen to make it out of something else.",
  ui_story_31110601_123_dialog_content = "Are you okay, Beryl?",
  ui_story_31110601_124_dialog_content = "Making something this elaborate must have taken all of your patience and mind, right?",
  ui_story_31110601_125_dialog_content = "I can tell, just from looking, I can feel your feelings from it.",
  ui_story_31110601_126_dialog_content = "I'm not upset about it. On the contrary...",
  ui_story_31110601_X104_dialog_content = "I'm actually pretty happy.",
  ui_story_31110601_127_dialog_content = "Don't you two think it's beautiful as it is, even now?",
  ui_story_31110601_128_dialog_content = "Against the backdrop of a rainbow in the cloudy sky, the falling rain looks like tears streaming down the maiden's face.",
  ui_story_31110601_130_dialog_content = "If her existence wasn't meant to be so short, she would never...",
  ui_story_31110601_131_dialog_content = "She would never be so full of life, here in this moment.",
  ui_story_31110601_132_dialog_content = "It's like those romantic scenes depicted in the books we've read.",
  ui_story_31110601_133_dialog_content = "... So you still like it even though it's wet, Beryl?",
  ui_story_31110601_134_dialog_content = "I just think that maybe... There's no point worrying about how to take it with us anymore.",
  ui_story_31110601_135_dialog_content = "Leaving it here isn't a bad idea, either... maybe someone else will get to see it, too.",
  ui_story_31110601_136_dialog_content = "You really have changed a lot, Beryl.",
  ui_story_31110601_137_dialog_content = "You've become so much more cheerful, someone who has learned to let go of things.",
  ui_story_31110601_138_dialog_content = "It's all thanks to you guys...",
  ui_story_31110601_139_dialog_content = "I'm done worrying about the past. I'm not afraid of my memories anymore.",
  ui_story_31110601_140_dialog_content = "<color=#e8d9bb>Beryl smiled, and it was different from the hesitant and anxious smiles she had before...</color>",
  ui_story_31110601_141_dialog_content = "<color=#e8d9bb>It was a joyful and infectious smile, one that made us do the same without us even realizing it.</color>",
  ui_story_31110601_142_dialog_content = "So now, I don't feel as though parting ways is such a bad thing.",
  ui_story_31110601_143_dialog_content = "Parting ways...?",
  ui_story_31110601_144_dialog_content = "That's right. Everyone will be going their separate ways tonight.",
  ui_story_31110601_145_dialog_content = "So not only will we be saying goodbye to your sandcastle, but to you as well, Beryl...",
  ui_story_31110601_146_dialog_content = "D-Don't worry, Raphael! I... I promise I'll come visit you in Lumopolis!",
  ui_story_31110601_147_dialog_content = "Oh, Beryl!",
  ui_story_31110601_148_dialog_content = "Even though we're parting ways, it's not like we won't see each other again! We'll make new memories in the future, okay?",
  ui_story_31110601_149_dialog_content = "Next year and the year after that, and every year after...",
  ui_story_31110601_150_dialog_content = "With Raphael... and you, PlayerName.",
  ui_story_31110601_151_dialog_content = "<color=#e8d9bb>Upon saying this, Beryl awkwardly lowered her head again.</color>",
  ui_story_31110601_152_dialog_content = "PlayerName...",
  ui_story_31110601_153_dialog_content = "You'll come and play on the beach with me again next year... right?",
  ui_story_31110601_154_option_content = "Absolutely."
}
return config
